insert into PTL_RECE_POSITION ( PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, INV_AIM, HODING_TYPE, REC_TYPE, CDATE, PAY_DATE, AMOUNT, CCY, P_FINPROD_ID, FACE_VALUE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) VALUES targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.INV_AIM, targetTable.HODING_TYPE, targetTable.REC_TYPE, #{batchDate,jdbcType=DATE}, targetTable.PAY_DATE, SUM(targetTable.AMOUNT), targetTable.CCY, null, null, 'system', null, NOW(), 'system', NOW() FROM ( SELECT PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, IFNULL(INV_AIM, '999999') as INV_AIM, HODING_TYPE, REC_TYPE, PAY_DATE, AMOUNT, CCY FROM PTL_RECE_POSITION WHERE HODING_TYPE != #{POSITION_TYPE_01,jdbcType=VARCHAR} and CDATE = #{lastDate,jdbcType=DATE} and AMOUNT != 0
and (
)
union all SELECT PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, IFNULL(INV_AIM, '999999') as INV_AIM, HODING_TYPE, REC_TYPE, PAY_DATE, SUM(AMOUNT), CCY FROM PTL_RECE_POSITION_FLOW WHERE HODING_TYPE != #{POSITION_TYPE_01,jdbcType=VARCHAR} and CDATE = #{batchDate,jdbcType=DATE}
and (
)
GROUP BY PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999'), FINPROD_ID, BRANCH, CCY, IFNULL(INV_AIM, '999999'), HODING_TYPE, REC_TYPE, PAY_DATE ) targetTable group by targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, targetTable.CCY, targetTable.INV_AIM, targetTable.REC_TYPE, targetTable.PAY_DATE
